<!doctype html><html lang="id"><head><meta charset="utf-8"><title>KRS</title><style>body{font:12px Arial;margin:35px}h2,h3{text-align:center;margin:4px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #555;padding:7px;text-align:left}.sign{display:flex;justify-content:space-between;margin-top:70px;text-align:center}.sign div{width:40%}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Cetak</button><h2>KARTU RENCANA STUDI</h2><h3>TAHUN AJARAN 2026/2027 GANJIL</h3><p>Nama: <?= esc($nama) ?><br>NIM: <?= esc($nim) ?></p><table><thead><tr><th>No</th><th>Kode</th><th>Mata Kuliah</th><th>SKS</th><th>Dosen</th></tr></thead><tbody><?php $total=0;foreach($rows as $i=>$r):$total+=$r['sks']; ?><tr><td><?= $i+1 ?></td><td><?= esc($r['kode']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['sks']) ?></td><td><?= esc($r['dosen']??'-') ?></td></tr><?php endforeach ?></tbody></table><p>Total SKS: <?= $total ?></p><div class="sign"><div>Mengetahui,<br>Dosen Wali<br><br><br><u><?= esc($wali??'________________') ?></u></div><div>Mahasiswa<br><br><br><br><u><?= esc($nama) ?></u></div></div></body></html>